171	bool SGIImage::readData(QImage &img)
172	{
173	    QRgb *c;
174	    quint32 *start = _starttab;
175	    QByteArray lguard(_xsize, 0);
176	    uchar *line = (uchar *)lguard.data();
177	    unsigned x, y;
178	
179	    if (!_rle) {
180	        _pos = _data.begin();
181	    }
182	
183	    for (y = 0; y < _ysize; y++) {
184	        if (_rle) {
185	            _pos = _data.begin() + *start++;
186	        }
187	        if (!getRow(line)) {
188	            return false;
189	        }
190	        c = (QRgb *)img.scanLine(_ysize - y - 1);
191	        for (x = 0; x < _xsize; x++, c++) {
192	            *c = qRgb(line[x], line[x], line[x]);
193	        }
194	    }
195	
196	    if (_zsize == 1) {
197	        return true;
198	    }
199	
200	    if (_zsize != 2) {
201	        for (y = 0; y < _ysize; y++) {
202	            if (_rle) {
203	                _pos = _data.begin() + *start++;
204	            }
205	            if (!getRow(line)) {
206	                return false;
207	            }
208	            c = (QRgb *)img.scanLine(_ysize - y - 1);
209	            for (x = 0; x < _xsize; x++, c++) {
210	                *c = qRgb(qRed(*c), line[x], line[x]);
211	            }
212	        }
213	
214	        for (y = 0; y < _ysize; y++) {
215	            if (_rle) {
216	                _pos = _data.begin() + *start++;
217	            }
218	            if (!getRow(line)) {
219	                return false;
220	            }
221	            c = (QRgb *)img.scanLine(_ysize - y - 1);
222	            for (x = 0; x < _xsize; x++, c++) {
223	                *c = qRgb(qRed(*c), qGreen(*c), line[x]);
224	            }
225	        }
226	
227	        if (_zsize == 3) {
228	            return true;
229	        }
230	    }
231	
232	    for (y = 0; y < _ysize; y++) {
233	        if (_rle) {
234	            _pos = _data.begin() + *start++;
235	        }
236	        if (!getRow(line)) {
237	            return false;
238	        }
239	        c = (QRgb *)img.scanLine(_ysize - y - 1);
240	        for (x = 0; x < _xsize; x++, c++) {
241	            *c = qRgba(qRed(*c), qGreen(*c), qBlue(*c), line[x]);
242	        }
243	    }
244	
245	    return true;
246	}
