518	void SGIImage::writeHeader()
519	{
520	    _stream << quint16(0x01da);
521	    _stream << _rle << _bpc << _dim;
522	    _stream << _xsize << _ysize << _zsize;
523	    _stream << _pixmin << _pixmax;
524	    _stream << quint32(0);
525	
526	    for (int i = 0; i < 80; i++) {
527	        _imagename[i] = '\0';
528	    }
529	    _stream.writeRawData(_imagename, 80);
530	
531	    _stream << _colormap;
532	    for (int i = 0; i < 404; i++) {
533	        _stream << quint8(0);
534	    }
535	}
536	
537	void SGIImage::writeRle()
538	{
539	    _rle = 1;
540	//     qDebug() << "writing RLE data";
541	    writeHeader();
542	    uint i;
543	
544	    // write start table
545	    for (i = 0; i < _numrows; i++) {
546	        _stream << quint32(_rlevector[_starttab[i]]->offset());
547	    }
548	
549	    // write length table
550	    for (i = 0; i < _numrows; i++) {
551	        _stream << quint32(_rlevector[_starttab[i]]->size());
552	    }
553	
554	    // write data
555	    for (i = 0; (int)i < _rlevector.size(); i++) {
556	        const_cast<RLEData *>(_rlevector[i])->write(_stream);
557	    }
558	}
559	
560	void SGIImage::writeVerbatim(const QImage &img)
561	{
562	    _rle = 0;
563	//     qDebug() << "writing verbatim data";
564	    writeHeader();
565	
566	    const QRgb *c;
567	    unsigned x, y;
568	
569	    for (y = 0; y < _ysize; y++) {
570	        c = reinterpret_cast<const QRgb *>(img.scanLine(_ysize - y - 1));
571	        for (x = 0; x < _xsize; x++) {
572	            _stream << quint8(qRed(*c++));
573	        }
574	    }
575	
576	    if (_zsize == 1) {
577	        return;
578	    }
579	
580	    if (_zsize != 2) {
581	        for (y = 0; y < _ysize; y++) {
582	            c = reinterpret_cast<const QRgb *>(img.scanLine(_ysize - y - 1));
583	            for (x = 0; x < _xsize; x++) {
584	                _stream << quint8(qGreen(*c++));
585	            }
586	        }
587	
588	        for (y = 0; y < _ysize; y++) {
589	            c = reinterpret_cast<const QRgb *>(img.scanLine(_ysize - y - 1));
590	            for (x = 0; x < _xsize; x++) {
591	                _stream << quint8(qBlue(*c++));
592	            }
593	        }
594	
595	        if (_zsize == 3) {
596	            return;
597	        }
598	    }
599	
600	    for (y = 0; y < _ysize; y++) {
601	        c = reinterpret_cast<const QRgb *>(img.scanLine(_ysize - y - 1));
602	        for (x = 0; x < _xsize; x++) {
603	            _stream << quint8(qAlpha(*c++));
604	        }
605	    }
606	}
